#!/bin/bash
# P25: leyes que el grafo cita como origen y cuyo encabezado en senado dice «Ley INEXEQUIBLE» sin citar la sentencia
# (origenes_revisar.txt, «muerte de la norma entera sin arista»). La sentencia se localizó por búsqueda web (solo como
# pista) y se comprobó contra su RESUELVE en la relatoría de la Corte Constitucional (ficha en jurisprudencia/):
# nombra la ley por número y año. Sin esa coincidencia textual no se registró nada.
cd "$(dirname "$0")" || exit 1
# Fichas que no estaban (las otras 9 sentencias y C-241/06, C-333/05, C-400/05, C-120/04, C-1338/00, C-781/04 ya existían):
